def execute_install(self):
    """
    Install one or more roles(``ansible-galaxy role install``), or one or more collections(``ansible-galaxy collection install``).
    You can pass in a list (roles or collections) or use the file
    option listed below (these are mutually exclusive). If you pass in a list, it
    can be a name (which will be downloaded via the galaxy API and github), or it can be a local tar archive file.
    """
    galaxy_type = context.CLIARGS['type']
    role_file = context.CLIARGS.get('role_file')
    collection_file = context.CLIARGS.get('requirements')
    requirements_file = role_file if galaxy_type == 'role' else collection_file
    requirements = None

    if requirements_file:
        requirements_file = GalaxyCLI._resolve_path(requirements_file)
        if galaxy_type == 'role' and not requirements_file.endswith(('.yml', '.yaml')):
            raise AnsibleError("Invalid role requirements file, it must end with a .yml or .yaml extension")
        requirements = self._parse_requirements_file(requirements_file, allow_old_format=galaxy_type == 'role')

        if galaxy_type == 'collection' and requirements['roles']:
            display.display("The requirements file '%s' contains roles which will be ignored. To install these roles run 'ansible-galaxy role install -r' or to install both at the same time run 'ansible-galaxy install -r' without a custom install path." % requirements_file)
        elif galaxy_type == 'role' and requirements['collections']:
            message = ("The requirements file '%s' contains collections which will be ignored. "
                       "To install these collections run 'ansible-galaxy collection install -r' or to install both "
                       "at the same time run 'ansible-galaxy install -r' without a custom install path." % requirements_file)
            if self._implicit_role and not self._custom_roles_path:
                pass  # Both types are installed below.
            elif self._implicit_role:
                display.warning("Collections cannot be installed to a roles path. " + message)
            else:
                display.vvv(message)

        if not requirements['roles'] and not requirements['collections']:
            display.display('Skipping install, no requirements found')
            return 0

    if galaxy_type == 'collection':
        return self._install_collections(requirements)

    if context.CLIARGS['args'] or (requirements and requirements['roles']):
        self._install_roles(requirements)
    elif not requirements_file:
        raise AnsibleOptionsError("- you must specify a user/role name or a roles file")

    if self._implicit_role and not self._custom_roles_path and requirements and requirements['collections']:
        return self._install_collections(requirements)
    if requirements and not requirements['roles']:
        display.display('Skipping role install, no roles found')
    return 0

def _install_collections(self, parsed_requirements=None):
    display.display('Starting galaxy collection install process')
    collections = context.CLIARGS['args']
    force = context.CLIARGS['force']
    output_path = context.CLIARGS.get('collections_path') or C.COLLECTIONS_PATHS[0]
    ignore_certs = context.CLIARGS['ignore_certs']
    ignore_errors = context.CLIARGS['ignore_errors']
    requirements_file = context.CLIARGS.get('requirements')
    no_deps = context.CLIARGS['no_deps']
    force_deps = context.CLIARGS['force_with_deps']

    if parsed_requirements is None:
        if collections and requirements_file:
            raise AnsibleError("The positional collection_name arg and --requirements-file are mutually exclusive.")
        elif not collections and not requirements_file:
            raise AnsibleError("You must specify a collection name or a requirements file.")

    if parsed_requirements is not None:
        requirements = parsed_requirements['collections']
    else:
        requirements = self._require_one_of_collections_requirements(collections, requirements_file)

    if not requirements:
        display.display('Skipping collection install, no collections found')
        return 0

    output_path = GalaxyCLI._resolve_path(output_path)
    collections_path = C.COLLECTIONS_PATHS

    if len([p for p in collections_path if p.startswith(output_path)]) == 0:
        display.warning("The specified collections path '%s' is not part of the configured Ansible "
                        "collections paths '%s'. The installed collection won't be picked up in an Ansible "
                        "run." % (to_text(output_path), to_text(":".join(collections_path))))

    output_path = validate_collection_path(output_path)
    b_output_path = to_bytes(output_path, errors='surrogate_or_strict')
    if not os.path.exists(b_output_path):
        os.makedirs(b_output_path)

    install_collections(requirements, output_path, self.api_servers, (not ignore_certs), ignore_errors,
                        no_deps, force, force_deps, context.CLIARGS.get('allow_pre_release', False))

    return 0

def _install_roles(self, parsed_requirements=None):
    display.display('Starting galaxy role install process')
    role_file = context.CLIARGS['role_file']

    if not context.CLIARGS['args'] and role_file is None:
        # the user needs to specify one of either --role-file or specify a single user/role name
        raise AnsibleOptionsError("- you must specify a user/role name or a roles file")

    no_deps = context.CLIARGS['no_deps']
    force_deps = context.CLIARGS['force_with_deps']

    force = context.CLIARGS['force'] or force_deps

    roles_left = []
    if role_file:
        roles_left = parsed_requirements['roles']
    else:
        # roles were specified directly, so we'll just go out grab them
        # (and their dependencies, unless the user doesn't want us to).
        for rname in context.CLIARGS['args']:
            role = RoleRequirement.role_yaml_parse(rname.strip())
            roles_left.append(GalaxyRole(self.galaxy, self.api, **role))

    for role in roles_left:
        # only process roles in roles files when names matches if given
        if role_file and context.CLIARGS['args'] and role.name not in context.CLIARGS['args']:
            display.vvv('Skipping role %s' % role.name)
            continue

        display.vvv('Processing role %s ' % role.name)
